  <div class="legend" data-testid="legend">
    @for (item of legend; track item.state) {
      <span class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
        <span class="swatch swatch-{{ item.state }}" aria-hidden="true"></span>{{ item.label }}
      </span>
    }
  </div>

  <div class="selected-seats" data-testid="selected-seats">
    <p class="selected-seats-count" data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</p>
    @for (line of selectedRows(); track line.row) {
      <p class="selected-seats-row" data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.seats }}</p>
    }
  </div>

  <div class="actions">
    <button matButton="outlined" type="button" data-testid="cancel-button">Cancel</button>
    <button matButton="filled" type="button" data-testid="continue-button" [disabled]="selectedCount() === 0">Continue</button>
  </div>
}

